// ============================================================
// CALCULER LES CHIFFRES DE LA SEMAINE
//   1. Chiffre d'affaires de la semaine écoulée vs la même semaine l'an dernier
//   2. Les clients qui montent et ceux qui baissent (4 dernières semaines vs l'an dernier)
//   3. Les produits qui partent le mieux et ceux qui montent
//   4. Les factures en retard, les clients dormants, les commandes reçues
// Tout est calculé ici, au centime près. L'IA ne fait que rédiger.
// ============================================================

const reglages = $('Réglages').first().json;
const ventes = $('Lire les ventes').all().map(item => item.json);
const factures = $('Lire les factures').all().map(item => item.json);
const commandes = $('Lire les commandes').all().map(item => item.json);

const UN_JOUR = 24 * 60 * 60 * 1000;

// --- Outils : lire une date et un nombre, quel que soit le format du tableur
function lireDate(valeur) {
  if (valeur === undefined || valeur === null || valeur === '') return null;
  if (typeof valeur === 'number') return new Date(Date.UTC(1899, 11, 30) + valeur * UN_JOUR);
  const texte = String(valeur).trim();
  let m = texte.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  m = texte.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));
  return null;
}
function lireNombre(valeur) {
  if (typeof valeur === 'number') return valeur;
  const texte = String(valeur ?? '').replace(/[\s  €]/g, '').replace(',', '.');
  return parseFloat(texte) || 0;
}
const euros = n => Math.round(n).toLocaleString('fr-FR').replace(/ /g, ' ') + ' €';
const evolution = (avant, apres) => (avant > 0 ? Math.round(((apres - avant) / avant) * 100) : null);
const jourMois = d => d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', timeZone: 'UTC' });

// --- Aujourd'hui (ou la date forcée dans Réglages)
const maintenant = $now.setZone('Europe/Paris');
const aujourdhui = lireDate(reglages.date_de_reference)
  ?? new Date(Date.UTC(maintenant.year, maintenant.month - 1, maintenant.day));

// --- La semaine écoulée : les 7 derniers jours de l'export des ventes
let derniereVente = 0;
for (const v of ventes) {
  const d = lireDate(v.date);
  if (d && d <= aujourdhui && d > derniereVente) derniereVente = d;
}
const finSemaine = new Date(derniereVente || aujourdhui);
const debutSemaine = new Date(finSemaine - 6 * UN_JOUR);
const debut4Semaines = new Date(finSemaine - 27 * UN_JOUR);
const UN_AN = 364 * UN_JOUR; // 52 semaines : on compare un lundi avec un lundi

const dans = (d, debut, fin) => d >= debut && d <= fin;

// 1. On additionne les ventes par période, par client et par produit
let caSemaine = 0, caSemaineN1 = 0, caAnnee = 0, caAnneeN1 = 0;
const clients = {}, produits = {};
const debutAnnee = new Date(Date.UTC(finSemaine.getUTCFullYear(), 0, 1));

for (const v of ventes) {
  const d = lireDate(v.date);
  if (!d) continue;
  const ca = lireNombre(v.ca_ht);

  if (dans(d, debutSemaine, finSemaine)) caSemaine += ca;
  if (dans(d, new Date(debutSemaine - UN_AN), new Date(finSemaine - UN_AN))) caSemaineN1 += ca;
  if (dans(d, debutAnnee, finSemaine)) caAnnee += ca;
  if (dans(d, new Date(debutAnnee - UN_AN), new Date(finSemaine - UN_AN))) caAnneeN1 += ca;

  const recent = dans(d, debut4Semaines, finSemaine);
  const anDernier = dans(d, new Date(debut4Semaines - UN_AN), new Date(finSemaine - UN_AN));
  if (!recent && !anDernier) continue;

  const c = (clients[v.client] ??= { client: v.client, type: v.type_client, recent: 0, anDernier: 0 });
  const p = (produits[v.produit] ??= { produit: v.produit, recent: 0, anDernier: 0 });
  if (recent) { c.recent += ca; p.recent += ca; }
  if (anDernier) { c.anDernier += ca; p.anDernier += ca; }
}

// 2. Clients et produits : l'écart en euros sur 4 semaines vs l'an dernier
const ligne = x => ({
  nom: x.client ?? x.produit,
  type: x.type,
  ca_4_semaines: euros(x.recent),
  ca_4_semaines_an_dernier: euros(x.anDernier),
  ecart: euros(x.recent - x.anDernier),
  evolution_pct: x.anDernier > 0 ? evolution(x.anDernier, x.recent) : 'nouveau, pas de ventes l\'an dernier',
  _ecart: x.recent - x.anDernier,
});
const listeClients = Object.values(clients).map(ligne);
const listeProduits = Object.values(produits).map(ligne);
const nettoyer = l => l.map(({ _ecart, ...reste }) => reste);

const clientsQuiBaissent = nettoyer(listeClients.filter(c => c._ecart < 0).sort((a, b) => a._ecart - b._ecart).slice(0, 3));
const clientsQuiMontent = nettoyer(listeClients.filter(c => c._ecart > 0).sort((a, b) => b._ecart - a._ecart).slice(0, 3));
const produitsQuiMontent = nettoyer(listeProduits.filter(p => p._ecart > 0).sort((a, b) => b._ecart - a._ecart).slice(0, 3));
const meilleursProduits = Object.values(produits).sort((a, b) => b.recent - a.recent).slice(0, 3)
  .map(p => ({ nom: p.produit, ca_4_semaines: euros(p.recent) }));

// 3. Factures en retard : pas payées et échéance dépassée
const enRetard = factures
  .filter(f => f.n_facture && String(f.payee).trim().toUpperCase() !== 'OUI')
  .map(f => ({ ...f, echeance: lireDate(f.date_echeance) }))
  .filter(f => f.echeance && f.echeance < aujourdhui)
  .map(f => ({
    client: f.client,
    facture: f.n_facture,
    montant: lireNombre(f.montant_ttc),
    jours_de_retard: Math.round((aujourdhui - f.echeance) / UN_JOUR),
  }))
  .sort((a, b) => b.montant - a.montant);
const totalEnRetard = enRetard.reduce((s, f) => s + f.montant, 0);

// 4. Clients dormants : rien commandé depuis plus de [seuil] fois leur rythme habituel
const joursParClient = {};
for (const v of ventes) {
  const d = lireDate(v.date);
  if (!d || d > aujourdhui || !v.client) continue;
  (joursParClient[v.client] ??= new Set()).add(d.getTime());
}
const seuil = Number(reglages.seuil_clients_dormants) || 2;
const dormants = Object.entries(joursParClient)
  .filter(([, jours]) => jours.size >= 3)
  .filter(([, jours]) => {
    const liste = [...jours].sort((a, b) => a - b);
    const rythme = (liste[liste.length - 1] - liste[0]) / UN_JOUR / (liste.length - 1);
    return (aujourdhui - liste[liste.length - 1]) / UN_JOUR > seuil * rythme;
  })
  .map(([client]) => client);

// 5. Commandes reçues la semaine écoulée (onglet Commandes)
const commandesSemaine = new Set(
  commandes
    .filter(c => c.n_commande && dans(lireDate(c.date_reception) ?? new Date(0), debutSemaine, finSemaine))
    .map(c => c.n_commande)
).size;

return [{
  json: {
    semaine: `du ${debutSemaine.getUTCMonth() === finSemaine.getUTCMonth() ? debutSemaine.getUTCDate() : jourMois(debutSemaine)} au ${jourMois(finSemaine)} ${finSemaine.getUTCFullYear()}`,
    ca_semaine: euros(caSemaine),
    ca_meme_semaine_an_dernier: euros(caSemaineN1),
    evolution_semaine_pct: evolution(caSemaineN1, caSemaine),
    ca_depuis_janvier: euros(caAnnee),
    evolution_depuis_janvier_pct: evolution(caAnneeN1, caAnnee),
    periode_comparaison_clients: `4 semaines du ${jourMois(debut4Semaines)} au ${jourMois(finSemaine)}, comparées aux mêmes 4 semaines l'an dernier`,
    clients_qui_baissent: clientsQuiBaissent,
    clients_qui_montent: clientsQuiMontent,
    produits_qui_montent: produitsQuiMontent,
    produits_qui_partent_le_mieux: meilleursProduits,
    factures_en_retard: { nombre: enRetard.length, total: euros(totalEnRetard), principales: enRetard.slice(0, 3).map(f => ({ ...f, montant: euros(f.montant) })) },
    clients_dormants: { nombre: dormants.length, noms: dormants },
    commandes_recues_par_mail_la_semaine: commandesSemaine || null, // null si l'onglet Commandes est vide
  },
}];

// ============================================================
// METTRE EN PAGE LE MAIL
// On met le texte de l'IA dans un gabarit sobre, avec les
// 4 chiffres clés en haut. Les couleurs se changent ici.
// ============================================================

const reglages = $('Réglages').first().json;
const chiffres = $('Calculer les chiffres de la semaine').first().json;
let texte = $json.text || '';

// Couleurs du gabarit
const ENCRE = '#1f2328', GRIS = '#6b6f76', FOND = '#f6f3ee', ACCENT = '#8a5a2b', VERT = '#1a7f37', ROUGE = '#b42318';

// 1. On nettoie le texte de l'IA et on lui donne un style lisible dans Gmail
texte = texte.replace(/```html|```/g, '').trim()
  // La phrase « À regarder cette semaine » est mise en valeur dans un encadré
  .replace(/<h3>\s*(À regarder cette semaine)\s*<\/h3>\s*<p>([\s\S]*?)<\/p>/i,
    `<div style="margin:26px 0 0;padding:14px 16px;background:${FOND};border-left:4px solid ${ACCENT};border-radius:4px;">` +
    `<div style="font-size:13px;font-weight:700;color:${ACCENT};text-transform:uppercase;letter-spacing:.06em;margin-bottom:4px;">$1</div>$2</div>`)
  .replace(/<h3>/g, `<h3 style="font-size:15px;margin:26px 0 8px;color:${ACCENT};text-transform:uppercase;letter-spacing:.06em;">`)
  .replace(/<p>/g, `<p style="margin:0 0 12px;">`)
  .replace(/<ul>/g, `<ul style="margin:0 0 12px;padding-left:20px;">`)
  .replace(/<li>/g, `<li style="margin:0 0 8px;">`)
  // Espaces insécables : « 68 884 € » ne se coupe jamais en fin de ligne
  .replace(/(\d) (?=\d{3}\b)/g, '$1&nbsp;')
  .replace(/(\d) (€|%)/g, '$1&nbsp;$2');

// 2. Les 4 chiffres clés en haut du mail
const signe = n => (n === null ? '' : n > 0 ? `+${n} %` : `${n} %`);
const couleur = n => (n === null ? GRIS : n >= 0 ? VERT : ROUGE);
const carte = (titre, valeur, detail, couleurDetail = GRIS) => `
  <td style="width:25%;padding:6px;vertical-align:top;">
    <div style="background:${FOND};border-radius:8px;padding:14px 12px;min-height:74px;">
      <div style="font-size:11px;color:${GRIS};text-transform:uppercase;letter-spacing:.05em;">${titre}</div>
      <div style="font-size:21px;font-weight:700;color:${ENCRE};margin-top:6px;">${valeur}</div>
      <div style="font-size:12px;color:${couleurDetail};margin-top:4px;">${detail}</div>
    </div>
  </td>`;

const cartes = [
  carte('CA de la semaine', chiffres.ca_semaine, `${signe(chiffres.evolution_semaine_pct)} vs l'an dernier`, couleur(chiffres.evolution_semaine_pct)),
  carte('Depuis janvier', chiffres.ca_depuis_janvier, `${signe(chiffres.evolution_depuis_janvier_pct)} vs l'an dernier`, couleur(chiffres.evolution_depuis_janvier_pct)),
  carte('Impayés', chiffres.factures_en_retard.total, `${chiffres.factures_en_retard.nombre} facture${chiffres.factures_en_retard.nombre > 1 ? 's' : ''} en retard`, chiffres.factures_en_retard.nombre ? ROUGE : GRIS),
  carte('Clients dormants', String(chiffres.clients_dormants.nombre), 'à relancer', chiffres.clients_dormants.nombre ? ROUGE : GRIS),
].join('');

// 3. Le mail complet
const html = `<!doctype html>
<html><body style="margin:0;padding:0;background:#ffffff;">
<div style="max-width:640px;margin:0 auto;padding:28px 20px;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;font-size:15px;line-height:1.6;color:${ENCRE};">
  <div style="font-size:12px;color:${ACCENT};text-transform:uppercase;letter-spacing:.12em;font-weight:600;">${reglages.nom_entreprise}</div>
  <h1 style="font-size:26px;margin:6px 0 2px;color:${ENCRE};">Le point du lundi</h1>
  <div style="font-size:14px;color:${GRIS};margin-bottom:18px;">Semaine ${chiffres.semaine}</div>
  <table role="presentation" style="width:100%;border-collapse:collapse;margin:0 -6px 8px;"><tr>${cartes}</tr></table>
  <div style="margin-top:14px;">${texte}</div>
  <div style="margin-top:30px;padding-top:14px;border-top:1px solid #e5e1da;font-size:12px;color:${GRIS};">
    Rapport préparé automatiquement chaque lundi à 7 h à partir des ventes et des factures.
  </div>
</div>
</body></html>`;

const evol = chiffres.evolution_semaine_pct;
return [{
  json: {
    destinataire: reglages.email_dirigeant,
    sujet: `Le point du lundi : ${chiffres.ca_semaine} la semaine dernière${evol === null ? '' : ` (${signe(evol)})`}`,
    html,
  },
}];
